style.css:
/* === Baby Powder Pink Theme with White Icons + Vibrant Pink Borders === */

/* Main background */
body, 
section, 
header, 
footer {
  background-color: #FFEFF7 !important; /* baby powder pink */
}

/* Keep pins/photos visible! */
div[data-test-id="pin"] {
  background-color: transparent !important; /* no cover over images */
  border-radius: 16px !important;
  box-shadow: 0px 3px 6px rgba(0,0,0,0.1) !important; /* subtle depth */
}

/* Pinterest logo + header icons → white inside */
header a,
header button,
header [role="button"] {
  color: #FFFFFF !important;
  border: 2px solid #FF4FA3 !important; /* vibrant pink border */
  border-radius: 50% !important;        /* circle style */
  padding: 6px !important;
  box-sizing: border-box !important;
}

/* SVG icons inside */
header a svg,
header button svg,
header [role="button"] svg {
  fill: #FFFFFF !important;
  stroke: #FFFFFF !important;
}

/* Image-based icons (profile pic, etc.) */
header a img,
header button img,
header [role="button"] img {
  filter: brightness(0) invert(1) !important;
}
